async function killTarget(namePattern, maxWait = 25000) {
  const target = sdk.findNearbyNpc(namePattern);
  if (!target) {
    console.log('No NPC matching', namePattern);
    return null;
  }
  console.log('Attacking', target.name, target.index, target.combatLevel);
  const atk = await bot.attack(target);
  if (!atk.success) {
    console.log('Attack failed:', atk.message);
    return null;
  }
  const start = Date.now();
  while (Date.now() - start < maxWait) {
    await sdk.waitForTicks(1);
    const s = sdk.getState();
    if (s?.player?.combat?.hp <= 5) {
      await bot.eatFood(/bread|shrimps|meat/i);
    }
    const npcStillThere = s?.nearbyNpcs.some(n => n.index === target.index);
    if (!npcStillThere) {
      console.log('Killed', target.name);
      return target.name;
    }
    if (!s?.player?.combat?.inCombat) {
      await sdk.waitForTicks(2);
      if (!sdk.getState()?.nearbyNpcs.some(n => n.index === target.index)) {
        console.log('Killed', target.name);
        return target.name;
      }
    }
  }
  return null;
}

